INSERT INTO roles(id,code,description) VALUES
('10000000-0000-0000-0000-000000000001','PLAYER','PickleTayo player'),('10000000-0000-0000-0000-000000000002','CLUB_ADMIN','Club administrator'),('10000000-0000-0000-0000-000000000003','COURT_OWNER','Court owner'),('10000000-0000-0000-0000-000000000004','STAFF','Platform staff'),('10000000-0000-0000-0000-000000000005','PLATFORM_ADMIN','Platform administrator');
INSERT INTO permissions(id,code,description) VALUES
('20000000-0000-0000-0000-000000000001','ACCOUNT_READ_SELF','Read own account'),('20000000-0000-0000-0000-000000000002','ACCOUNT_UPDATE_SELF','Update own account'),('20000000-0000-0000-0000-000000000003','SESSION_MANAGE_SELF','Manage own sessions'),('20000000-0000-0000-0000-000000000004','PLATFORM_USERS_MANAGE','Manage platform users');
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE (r.code='PLAYER' AND p.code IN ('ACCOUNT_READ_SELF','ACCOUNT_UPDATE_SELF','SESSION_MANAGE_SELF')) OR r.code='PLATFORM_ADMIN';
